    "lp2_hero_h1_lead": "Google Meet තුළ පැමිණීම සටහන් කරන්න ",
    "lp2_hero_sub": "ඔබේ Meet පැති පැනලයේ සජීවී ලැයිස්තුවක්: කවුද එක්වූයේ, කවුද ප්‍රමාද වූයේ, කවුද ඉවත් වූයේ සහ කොපමණ කාලයක්. එක් ක්ලික් කිරීමකින් පිරිසිදු වාර්තාවක් Google Sheets හෝ CSV වෙත යයි.",
    "lp2_how_s1_body": "ඕනෑම ඇමතුමක් අතරතුර පැති පැනලය විවෘත කරන්න. ඔබේ Google ගිණුමෙන් එක් වරක් පුරනය වන්න.",
    "lp2_how_s1_title": "Meet තුළ විවෘත කරන්න",
