    "lp2_how_s3_body": "එක් ක්ලික් කිරීමකින් සම්පූර්ණ වාර්තාව ඔබේ Drive හි Google Sheet එකකට යයි, අනුපිළිවෙළට සැකසීමට, බෙදාගැනීමට හෝ සංරක්ෂණය කිරීමට සූදානම්ව.",
    "lp2_how_s3_title": "අපනයනය",
