    "lp2_who_2_body": "කවුද සහභාගී වූයේ සහ කොපමණ වේලාවක් සිටියේද යන්න නිවැරදිව දැනගන්න. සහතික සහ පසු විපරම සඳහා Sheets වෙත අපනයනය කරන්න.",
    "lp2_who_2_tag": "සිදුවීම්",
    "lp2_who_2_title": "වෙබිනාර් සත්කාරකයින්",
    "lp2_who_3_body": "පුනරාවර්තන ඇමතුම්වල ස්ටෑන්ඩප් සහ රැස්වීම් සහභාගිත්වය නිරීක්ෂණය කරන්න, Slack, Google Chat හෝ Discord වෙත සාරාංශ සමඟ.",
    "lp2_who_3_tag": "කණ්ඩායම්",
    "lp2_who_3_title": "කණ්ඩායම් නායකයින්",
    "lp2_who_4_body": "බිල් කළ හැකි පැය තහවුරු කරන මිනිත්තුවෙන් මිනිත්තුවට සැසි සටහන්, 1-න්-1 ඇමතුම් සඳහා පවා.",
    "lp2_who_4_tag": "උපකාරක පන්ති",
