    "lp2_faq_a5": "Guddigu wuxuu ku shaqeeyaa browser-yada desktop-ka (Chrome, Edge, Safari, Firefox). Ka eeg oo wadaag warbixinnada taleefan kasta attendancetracker.dev.",
