    "history.noMeetingsMatch": "பொருந்தும் கூட்டங்கள் இல்லை.",
    "history.noPeople": "இதுவரை எந்த நபரும் கண்காணிக்கப்படவில்லை.",
    "history.noPeopleMatch": "பொருந்தும் நபர்கள் இல்லை.",
    "history.noSeries": "இதுவரை தொடர் கூட்டங்கள் எதுவும் தொகுக்கப்படவில்லை. Google Calendar தொடரிலிருந்து ஒரு கூட்டத்தை 2+ முறை கண்காணியுங்கள் — ஒவ்வொரு நபரின் வருகை விவரமும் இங்கே தோன்றும்.",
    "history.noSeriesMatch": "அந்தத் தேடலுக்குப் பொருந்தும் தொடர் இல்லை.",
