    "lp2_who_1_body": "பங்கேற்பாளர் பட்டியலைக் கையால் சரிபார்ப்பதை நிறுத்துங்கள். உங்கள் Google Classroom பட்டியலை இறக்குமதி செய்து ஒவ்வொரு வகுப்பிற்கும் தானியங்கு வருகைப் பதிவைப் பெறுங்கள்.",
