    "lp2_who_3_tag": "குழுக்கள்",
    "lp2_who_3_title": "குழுத் தலைவர்கள்",
    "lp2_who_4_body": "கட்டண மணிநேரங்களை உறுதிப்படுத்தும் நிமிடத்திற்கு நிமிடம் அமர்வுப் பதிவுகள், 1-க்கு-1 அழைப்புகளுக்கும் கூட.",
