    "lp2_cmp_title": "ఎక్స్‌టెన్షన్ కంటే add-on ఎందుకు మెరుగు",
    "lp2_faq_a1": "అవును. వ్యక్తిగత @gmail.com, Workspace Starter నుండి Enterprise వరకు, మరియు ప్రతి Education స్థాయి.",
    "lp2_faq_a2": "లేదు. Google అంతర్నిర్మిత నివేదికకు అర్హత ఉన్న చెల్లింపు ఎడిషన్ అవసరం. Attendance Tracker ఉచిత Gmail మరియు Education Fundamentals సహా అన్నింటిలోనూ పనిచేస్తుంది.",
    "lp2_faq_a3": "హోస్ట్ నేరుగా ట్రాక్ చేయగలరు. TA లేదా కో-హోస్ట్ కోసం, Workspace నిర్వాహకుడు ఒకసారి delegation ఆన్ చేస్తారు (attendancetracker.dev/setup వద్ద 2 నిమిషాలు).",
    "lp2_faq_a4": "Lifetime ఒకే చెల్లింపు. వార్షిక ప్లాన్‌లు సంవత్సరానికి ఒకసారి మాత్రమే పునరుద్ధరించబడతాయి, మరియు మీరు ఎప్పుడైనా రద్దు చేయవచ్చు.",
    "lp2_faq_a5": "ప్యానెల్ డెస్క్‌టాప్ బ్రౌజర్‌లలో (Chrome, Edge, Safari, Firefox) నడుస్తుంది. attendancetracker.dev వద్ద ఏ ఫోన్ నుండైనా నివేదికలను చూడండి మరియు పంచుకోండి.",
    "lp2_faq_more": "మరిన్ని ప్రశ్నలు ఉన్నాయా? సహాయ కేంద్రాన్ని సందర్శించండి →",
    "lp2_faq_q1": "ఇది వ్యక్తిగత Gmail ఖాతాతో పనిచేస్తుందా?",
    "lp2_faq_q2": "నాకు Google Workspace for Education Plus అవసరమా?",
    "lp2_faq_q3": "హోస్ట్ కాకుండా వేరొకరు ట్రాక్ చేయగలరా?",
    "lp2_faq_q4": "నాకు మళ్లీ ఛార్జ్ చేయబడుతుందా?",
    "lp2_faq_q5": "ఇది Meet మొబైల్ యాప్‌లో పనిచేస్తుందా?",
    "lp2_faq_title": "తెలుసుకోవాల్సినవి",
    "lp2_feat_1_body": "మీ Google Calendar ఆహ్వానంతో సరిపోల్చబడుతుంది. అనుమతి ఉన్న గైర్హాజరులను ఒక్క ట్యాప్‌తో గుర్తించండి.",
    "lp2_feat_1_title": "ఆలస్యంగా వచ్చేవారు మరియు రానివారు",
    "lp2_feat_2_body": "మీ తరగతి జాబితా ఒక్క క్లిక్‌లో.",
    "lp2_feat_2_title": "Google Classroom దిగుమతి",
    "lp2_feat_3_body": "ప్రతి సెషన్‌కు లేదా మొత్తం సెమిస్టర్‌కు దిగుమతికి సిద్ధమైన CSV-లు.",
    "lp2_feat_3_title": "Moodle మరియు Canvas గ్రేడ్‌బుక్‌లు",
    "lp2_feat_4_body": "ప్రతి పునరావృత సెషన్‌లో హాజరు % మరియు వరుసలు.",
    "lp2_feat_4_title": "సెమిస్టర్ మరియు స్ప్రింట్ ధోరణులు",
    "lp2_feat_5_body": "ట్రాక్ చేసిన ప్రతి సమావేశం సేవ్ అవుతుంది. ఏ పరికరం నుండైనా తెరవండి, పంచుకోండి లేదా ఎగుమతి చేయండి.",
    "lp2_feat_5_title": "సమావేశ చరిత్ర",
    "lp2_feat_6_body": "ప్రతిదానికీ /verify వద్ద ఎవరైనా తనిఖీ చేయగల పబ్లిక్ కోడ్ ఉంటుంది.",
    "lp2_feat_6_title": "ధృవీకరించదగిన సర్టిఫికెట్లు",
    "lp2_feat_7_body": "ప్రతి సమావేశం తర్వాత ఒక సారాంశ కార్డ్.",
    "lp2_feat_7_title": "Slack, Chat, Discord మరియు Gmail సారాంశాలు",
    "lp2_feat_8_body": "స్పానిష్, పోర్చుగీస్, హిందీ, తగలాగ్, ఉక్రేనియన్, అరబిక్ మరియు మరిన్ని.",
    "lp2_feat_8_title": "60 భాషలు",
    "lp2_feat_title": "మీకు కావాల్సిన మిగతావన్నీ",
    "lp2_final_btn": "Google Workspace Marketplace నుండి ఇన్‌స్టాల్ చేయండి",
    "lp2_final_fine": "ఉచితంగా ప్రారంభించండి · అపరిమిత వినియోగానికి ఒక్కసారి $9.99 · రద్దు చేయాల్సిన పని లేదు",
    "lp2_final_sub": "30 సెకన్లలో ఇన్‌స్టాల్ చేసి, మీ తదుపరి Google Meet కాల్‌నే ట్రాక్ చేయండి.",
    "lp2_final_title": "చివరిసారిగా చేతితో హాజరు తీసుకోండి.",
    "lp2_hero_btn_demo": "డెమో చూడండి",
    "lp2_hero_btn_install": "Marketplace నుండి ఇన్‌స్టాల్ చేయండి",
    "lp2_hero_eyebrow": "అధికారిక Google Workspace add-on",
    "lp2_hero_h1_accent": "స్వయంచాలకంగా తీసుకోండి.",
    "lp2_hero_h1_lead": "Google Meet-లో హాజరును ",
    "lp2_hero_sub": "మీ Meet సైడ్ ప్యానెల్‌లో లైవ్ జాబితా: ఎవరు చేరారు, ఎవరు ఆలస్యం, ఎవరు వెళ్లిపోయారు, ఎంతసేపు. ఒక్క క్లిక్‌తో శుభ్రమైన నివేదిక Google Sheets లేదా CSV కు వెళ్తుంది.",
    "lp2_how_s1_body": "ఏ కాల్ సమయంలోనైనా సైడ్ ప్యానెల్ తెరవండి. మీ Google ఖాతాతో ఒకసారి సైన్ ఇన్ చేయండి.",
    "lp2_how_s1_title": "Meet-లో తెరవండి",
    "lp2_how_s2_body": "జాబితా లైవ్‌గా నిండుతుంది: ప్రతి పాల్గొనేవారి చేరికలు, నిష్క్రమణలు, ఆలస్యాలు మరియు మొత్తం నిమిషాలు.",
    "lp2_how_s2_title": "Start క్లిక్ చేయండి",
    "lp2_how_s3_body": "ఒక్క క్లిక్‌తో పూర్తి నివేదిక మీ Drive-లోని Google Sheet కు వెళ్తుంది, క్రమబద్ధీకరించడానికి, పంచుకోవడానికి లేదా భద్రపరచడానికి సిద్ధంగా.",
    "lp2_how_s3_title": "ఎగుమతి",
    "lp2_how_sub": "సెటప్ అవసరం లేదు, విడిగా ఇన్‌స్టాల్ చేయాల్సిన ఎక్స్‌టెన్షన్ లేదు. ఏ Google Meet కాల్‌లోనైనా ప్యానెల్ తెరిచి మొదలుపెట్టండి.",
    "lp2_how_title": "\"ఎవరు ఉన్నారు?\" నుండి శుభ్రమైన Sheet వరకు",
    "lp2_mobile_sticky_btn": "ఉచితంగా ఇన్‌స్టాల్ చేయండి",
