    "lp2_priv_2": "టోకెన్‌లు AES-256-GCM తో ఎన్‌క్రిప్ట్ చేసి నిల్వ చేయబడతాయి",
    "lp2_priv_3": "విస్తృత Chrome అనుమతులు లేదా స్క్రీన్ స్క్రేపింగ్ లేదు",
    "lp2_priv_sub": "డేటా మీ స్వంత Google ఖాతాలోనే ఉంటుంది. మేము మీ సమావేశాలను ఎప్పుడూ అమ్మము, పంచుకోము, శిక్షణకు ఉపయోగించము.",
    "lp2_priv_title": "రూపకల్పనలోనే గోప్యత",
    "lp2_proof_1_body": "Google Meet REST APIs పై నిర్మించబడింది. స్క్రీన్ స్క్రేపింగ్ లేదు.",
    "lp2_proof_1_title": "అధికారిక Meet add-on",
    "lp2_proof_2_body": "అలాగే ప్రతి Workspace మరియు Education స్థాయిలో.",
    "lp2_proof_2_title": "వ్యక్తిగత Gmail పనిచేస్తుంది",
    "lp2_proof_3_body": "1-కి-1 ట్యూషన్ నుండి 200 మంది విద్యార్థుల ఉపన్యాసాల వరకు.",
